#!/usr/bin/env python3
"""Build an autoinstall.yaml for an unattended Ubuntu Desktop install.

Asks for the username, computer name and password, then writes the file.
The password is turned into a SHA-512 crypt hash on this computer; the plain
password is never written anywhere.

Usage:
  python3 make-autoinstall.py <public key file> <output file>

Needs passlib:  python3 -m pip install passlib
"""
import getpass
import pathlib
import re
import sys

from passlib.hash import sha512_crypt

TEMPLATE = """\
# Generated by scripts/make-autoinstall.py. Contains a password hash: do not publish.
autoinstall:
  version: 1
  locale: en_US.UTF-8
  keyboard:
    layout: us
  timezone: {timezone}
  identity:
    realname: "{realname}"
    hostname: {hostname}
    username: {username}
    password: "{password_hash}"
  ssh:
    install-server: true
    allow-pw: false
    authorized-keys:
      - {public_key}
  storage:
    layout:
      name: direct
      # The smallest disk is the Mac's internal SSD. The external installer
      # drive is far bigger, so it can never be picked.
      match:
        size: smallest
  drivers:
    install: true
  codecs:
    install: true
  updates: security
  late-commands:
    # Keep the Wi-Fi network chosen in the installer, so the server comes back
    # online by itself after the first restart.
    - "mkdir -p /target/etc/NetworkManager/system-connections"
    - "cp -a /etc/NetworkManager/system-connections/. /target/etc/NetworkManager/system-connections/ 2>/dev/null || true"
    - "cp -a /run/NetworkManager/system-connections/. /target/etc/NetworkManager/system-connections/ 2>/dev/null || true"
    - "chmod 600 /target/etc/NetworkManager/system-connections/* 2>/dev/null || true"
    # Run like a server: ignore the lid and never sleep.
    - "mkdir -p /target/etc/systemd/logind.conf.d"
    - "printf '[Login]\\nHandleLidSwitch=ignore\\nHandleLidSwitchExternalPower=ignore\\nHandleLidSwitchDocked=ignore\\n' > /target/etc/systemd/logind.conf.d/10-server-lid.conf"
    - "curtin in-target -- systemctl mask sleep.target suspend.target hibernate.target hybrid-sleep.target"
  shutdown: reboot
"""


TIMEZONE_HINTS = {
    "phoenix": "America/Phoenix",
    "arizona": "America/Phoenix",
    "detroit": "America/Detroit",
    "atlanta": "America/New_York",
    "new york": "America/New_York",
    "chicago": "America/Chicago",
    "denver": "America/Denver",
    "los angeles": "America/Los_Angeles",
}


def ask(prompt, default):
    answer = input(f"{prompt} [{default}]: ").strip()
    return answer or default


def main():
    key_file, out_file = sys.argv[1], sys.argv[2]
    public_key = pathlib.Path(key_file).expanduser().read_text().strip()

    print("Settings for the new Ubuntu install. Press Return to keep the value in brackets.")
    username, realname, hostname, timezone = "ian", "", "homeserver", "America/Phoenix"
    while True:
        username = ask("Username (lowercase, no spaces)", username)
        realname = ask("Full name", realname or username)
        hostname = ask("Computer name", hostname)
        timezone = ask("Time zone", timezone)
        # Fix the two mistakes the installer rejects: spaces in the computer
        # name, and a city on its own instead of Region/City.
        hostname = re.sub(r"[^a-z0-9-]+", "-", hostname.lower()).strip("-")
        if "/" not in timezone:
            timezone = TIMEZONE_HINTS.get(timezone.lower(), timezone)
        if not re.fullmatch(r"[a-z][a-z0-9_-]*", username) or "/" not in timezone:
            print("Username must be lowercase letters, numbers, - or _. Time zone looks like America/Phoenix. Try again.")
            continue
        print(f"\n  Username: {username}\n  Full name: {realname}\n  Computer name: {hostname}\n  Time zone: {timezone}\n")
        if ask("Is this right? Type n to change something", "y").lower().startswith("y"):
            break

    while True:
        first = getpass.getpass("Password for the new account (nothing shows as you type): ")
        second = getpass.getpass("Same password again: ")
        if first and first == second:
            break
        print("They did not match or were empty. Try again.")

    text = TEMPLATE.format(
        timezone=timezone,
        realname=realname.replace('"', ""),
        hostname=hostname,
        username=username,
        password_hash=sha512_crypt.using(rounds=5000).hash(first),
        public_key=public_key,
    )
    out = pathlib.Path(out_file)
    out.write_text(text)
    out.chmod(0o600)
    print(f"Wrote {out}. Username: {username}, computer name: {hostname}.")


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nStopped. Nothing was written. Run the command again to start over.")
